package com.mallcloud.order.service;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.mallcloud.api.cart.CartLine; import com.mallcloud.api.client.*; import com.mallcloud.api.order.*; import com.mallcloud.api.product.ProductSnapshot; import com.mallcloud.api.stock.*;
import com.mallcloud.common.api.PageResponse; import com.mallcloud.common.error.*; import com.mallcloud.common.id.SnowflakeIdGenerator; import com.mallcloud.order.dto.*; import com.mallcloud.order.entity.*; import com.mallcloud.order.mapper.*;
import org.springframework.dao.DuplicateKeyException; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal; import java.time.*; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;

@Service public class OrderService {
 private final OrderMapper orderMapper;private final OrderItemMapper itemMapper;private final ProductClient productClient;private final CartClient cartClient;private final StockClient stockClient;
 private final OrderPersistenceService persistence;private final SnowflakeIdGenerator ids;private final StringRedisTemplate redis;
 public OrderService(OrderMapper o,OrderItemMapper i,ProductClient p,CartClient c,StockClient s,OrderPersistenceService ps,SnowflakeIdGenerator ids,StringRedisTemplate redis){orderMapper=o;itemMapper=i;productClient=p;cartClient=c;stockClient=s;persistence=ps;this.ids=ids;this.redis=redis;}
 public OrderSummary createFromCart(Long userId,CreateOrderRequest request){List<CartLine> lines=cartClient.checkedItems(userId);if(lines.isEmpty())throw new BizException(ErrorCode.BAD_REQUEST,"请先勾选购物车商品");return create(userId,request.requestNo(),lines,request.receiverName(),request.receiverPhone(),request.receiverAddress(),true);}
 public OrderSummary createDirect(DirectOrderRequest request){ProductSnapshot p=productClient.findById(request.productId());if(p==null||!p.available())throw new BizException(ErrorCode.PRODUCT_UNAVAILABLE);BigDecimal price=request.unitPrice()==null?p.price():request.unitPrice();if(price.signum()<=0||price.compareTo(p.price())>0)throw new BizException(ErrorCode.BAD_REQUEST,"活动价格无效");CartLine line=new CartLine(p.id(),p.productName(),p.mainImage(),price,request.quantity(),true,LocalDateTime.now());return create(request.userId(),request.requestNo(),List.of(line),request.receiverName(),request.receiverPhone(),request.receiverAddress(),false);}
 private OrderSummary create(Long userId,String requestNo,List<CartLine> clientLines,String name,String phone,String address,boolean cleanCart){
  OrderEntity old=findByRequest(userId,requestNo);if(old!=null)return summary(old);String lockKey="mall:order:idem:"+userId+":"+requestNo;
  if(!Boolean.TRUE.equals(redis.opsForValue().setIfAbsent(lockKey,"PROCESSING",Duration.ofMinutes(10)))){old=findByRequest(userId,requestNo);if(old!=null)return summary(old);throw new BizException(ErrorCode.DUPLICATE_REQUEST);}
  List<Long> productIds=clientLines.stream().map(CartLine::productId).toList();Map<Long,ProductSnapshot> products=productClient.findByIds(productIds).stream().collect(Collectors.toMap(ProductSnapshot::id,Function.identity()));
  List<CartLine> verified=new ArrayList<>();for(CartLine line:clientLines){ProductSnapshot p=products.get(line.productId());if(p==null||!p.available())throw new BizException(ErrorCode.PRODUCT_UNAVAILABLE,"商品 "+line.productId()+" 已下架");verified.add(new CartLine(p.id(),p.productName(),p.mainImage(),p.price(),line.quantity(),true,line.createTime()));}
  long id=ids.nextId();String orderNo=String.valueOf(id);BigDecimal total=verified.stream().map(x->x.price().multiply(BigDecimal.valueOf(x.quantity()))).reduce(BigDecimal.ZERO,BigDecimal::add);
  OrderEntity order=new OrderEntity();order.setId(id);order.setOrderNo(orderNo);order.setRequestNo(requestNo);order.setUserId(userId);order.setTotalAmount(total);order.setPayAmount(total);order.setStatus("PENDING_PAYMENT");order.setReceiverName(name);order.setReceiverPhone(phone);order.setReceiverAddress(address);order.setCreateTime(LocalDateTime.now());
  StockReservationRequest stockRequest=new StockReservationRequest(orderNo,verified.stream().map(x->new StockItem(x.productId(),x.quantity())).toList());stockClient.reserve(stockRequest);
  try{persistence.save(order,verified);}catch(RuntimeException e){try{stockClient.release(stockRequest);}catch(Exception suppressed){e.addSuppressed(suppressed);}redis.delete(lockKey);throw e;}
  redis.opsForValue().set(lockKey,orderNo,Duration.ofDays(1));if(cleanCart)try{cartClient.removeItems(userId,productIds);}catch(Exception ignored){}return summary(order);
 }
 public OrderDetail detail(String orderNo,Long requester,boolean admin){OrderEntity o=find(orderNo);if(!admin&&!o.getUserId().equals(requester))throw new BizException(ErrorCode.FORBIDDEN);List<OrderItemEntity> items=itemMapper.selectList(new LambdaQueryWrapper<OrderItemEntity>().eq(OrderItemEntity::getOrderNo,orderNo));return new OrderDetail(summary(o),items.stream().map(x->new OrderItemView(x.getProductId(),x.getProductName(),x.getProductImage(),x.getProductPrice(),x.getQuantity(),x.getTotalAmount())).toList(),o.getReceiverName(),o.getReceiverPhone(),o.getReceiverAddress());}
 public PageResponse<OrderSummary> page(Long userId,boolean admin,long page,long size){LambdaQueryWrapper<OrderEntity> q=new LambdaQueryWrapper<OrderEntity>().eq(!admin,OrderEntity::getUserId,userId).orderByDesc(OrderEntity::getCreateTime);Page<OrderEntity> p=orderMapper.selectPage(Page.of(page,size),q);return PageResponse.of(p.getRecords().stream().map(this::summary).toList(),page,size,p.getTotal());}
 @Transactional public void cancel(String orderNo,Long userId){OrderEntity o=find(orderNo);if(!o.getUserId().equals(userId))throw new BizException(ErrorCode.FORBIDDEN);if(!"PENDING_PAYMENT".equals(o.getStatus()))throw new BizException(ErrorCode.ORDER_STATE_INVALID);o.setStatus("CANCELLED");o.setCancelTime(LocalDateTime.now());orderMapper.updateById(o);stockClient.release(stockRequest(o));}
 @Transactional public void ship(String orderNo){OrderEntity o=find(orderNo);if(!"PAID".equals(o.getStatus()))throw new BizException(ErrorCode.ORDER_STATE_INVALID);o.setStatus("SHIPPED");o.setShipTime(LocalDateTime.now());orderMapper.updateById(o);}
 @Transactional public void complete(String orderNo,Long userId){OrderEntity o=find(orderNo);if(!o.getUserId().equals(userId))throw new BizException(ErrorCode.FORBIDDEN);if(!"SHIPPED".equals(o.getStatus()))throw new BizException(ErrorCode.ORDER_STATE_INVALID);o.setStatus("COMPLETED");o.setFinishTime(LocalDateTime.now());orderMapper.updateById(o);}
 public OrderEntity find(String no){OrderEntity o=orderMapper.selectOne(new LambdaQueryWrapper<OrderEntity>().eq(OrderEntity::getOrderNo,no));if(o==null)throw new BizException(ErrorCode.NOT_FOUND,"订单不存在");return o;}
 public OrderSummary findSummary(String no){return summary(find(no));}
 private OrderEntity findByRequest(Long uid,String request){return orderMapper.selectOne(new LambdaQueryWrapper<OrderEntity>().eq(OrderEntity::getUserId,uid).eq(OrderEntity::getRequestNo,request));}
 StockReservationRequest stockRequest(OrderEntity o){List<OrderItemEntity> items=itemMapper.selectList(new LambdaQueryWrapper<OrderItemEntity>().eq(OrderItemEntity::getOrderNo,o.getOrderNo()));return new StockReservationRequest(o.getOrderNo(),items.stream().map(x->new StockItem(x.getProductId(),x.getQuantity())).toList());}
 OrderSummary summary(OrderEntity o){return new OrderSummary(o.getOrderNo(),o.getUserId(),o.getTotalAmount(),o.getPayAmount(),o.getStatus(),o.getCreateTime(),o.getPayTime());}
}
